function commit(state: EditorState, scene: IsoSceneFile, extra: Partial<EditorState> = {}): EditorState {
  return {
    ...state,
    ...extra,
    scene,
    past: [...state.past, cloneScene(state.scene)].slice(-HISTORY_CAP),
    future: [],
    drag: null,
    resize: null,
    revision: state.revision + 1,
